INSERT INTO f_seed_members SELECT member_key,group_id FROM (SELECT *,count() OVER (PARTITION BY group_id) AS members FROM (SELECT group_id,member_key FROM (SELECT group_id,member_key,deleted,row_number() OVER (PARTITION BY group_id,member_key ORDER BY updated_at DESC,deleted DESC) AS rn FROM group_members WHERE group_id IN (unhex('6731'),unhex('6732'),unhex('6c61726765'))) WHERE rn=1 AND deleted=0 AND member_key NOT IN ('anyone','authenticated','anon'))) WHERE members<2000